// Раси й підраси поза базовими дев’ятьма (див. RACES у rules.js).
// Лише ігрова механіка; описи рис — власними словами, коротко.
//
// Поля:
//  n — назва; g — група (для списку); src — книга
//  asi — фіксовані бонуси {con: 2} або 'flex' (MPMM: +2/+1 чи +1/+1/+1 на вибір); choose — {count, amount, exclude}
//  size — 'M' | 'S' | 'SM' (на вибір); type — тип істоти, якщо не гуманоїд
//  speed — ходьба; fly / swim / climb / burrow — число або true (= ходьбі)
//  dark — темний зір у футах; hpLvl — +ХП за рівень
//  skills — навички; pick — [{n, from}] навички на вибір; langs / lang — мови й скільки на вибір
//  armor / weapons / tools / tool:{count, from} — володіння
//  ac — природна броня {base, ab} | {flat}; acBonus — +КЗ
//  nat — природна зброя [{n, d: '1к6', t: 'рубальна', ab}]
//  spells — вроджені закляття [[рівень персонажа, id]]; cantrips — пул замовлянь {name, lists, count}
//  res — ресурси [{id, n, max: число | 'prof' | 'con'…, rest: 'long'|'short', cost: ['bonus'…], note, any}]
//  std — стандартні дії бонусною дією {dash: {note, res}}; batk — бонусна атака {n, w: -1, need: 'dash'|'atk', res}
//  feat — риса на 1 рівні; choices — вибори раси [{id, name, options:[{id, name, desc, skills}]}]
//  tr — риси [[назва, опис]]

const T = (n, d) => [n, d];
